/**
 * The standard browser-side Web Channel client (WS-8).
 *
 * Generated by `pnpm init:web` from
 * `standards/web-scaffold/hosted-runtime/web-channel-client.ts`; the file is deliberately
 * dependency-free so every package Web can bundle it unchanged. The hosted runtime owns the
 * server half of the channel; this module owns the page half:
 *
 *   - connects `GET /_thefoolai/v1/web-channel` (SSE downlink) with the browser session cookie;
 *   - receives `invoke` messages and runs them through the page's intent-level action surface
 *     (`describe` / `state` / `invoke` — never DOM selectors or coordinates);
 *   - posts `result` / `error` and `statePublish` back to `POST /_thefoolai/v1/web-channel/invoke`;
 *   - treats `superseded` as terminal (a newer page instance owns the channel) and reconnects
 *     with capped backoff after an accidental stream loss.
 *
 * The channel is fail-closed by design: while it is not connected, agent invocations of
 * page-bound capabilities fail with `page_not_connected` on the runtime side. This client never
 * queues work on behalf of the agent.
 */

export const WEB_CHANNEL_VERSION = "1.1.0";

/** The statePublish uplink was added in Web Channel 1.1.0. */
export function supportsStatePublish(channelVersion: unknown): boolean {
  if (typeof channelVersion !== "string") return false;
  const [majorPart, minorPart = "0"] = channelVersion.split(".");
  if (!/^\d+$/.test(majorPart) || !/^\d+$/.test(minorPart)) return false;
  const major = Number(majorPart);
  const minor = Number(minorPart);
  return major > 1 || (major === 1 && minor >= 1);
}

/** The package-owned action surface shape every standard bridge must expose. */
export interface WebChannelActionSurface {
  readonly routeId: string;
  describe(): readonly unknown[];
  state(): Record<string, unknown>;
  invoke(actionId: string, input?: unknown): Promise<unknown>;
}

export interface WebChannelClientOptions {
  /**
   * Called after the downlink connects or disconnects. Optional; the surface may use it to
   * surface `pageConnected` in its own runtime state.
   */
  readonly onStateChange?: (connected: boolean) => void;
  /** Called after `hello` confirms this client may publish page state. */
  readonly onChannelReady?: () => void;
  /** Maximum reconnect attempts after an accidental stream loss. Default 5. */
  readonly maxReconnects?: number;
}

export interface WebChannelClient {
  /** Whether the downlink is currently connected. */
  readonly connected: boolean;
  /** Stops the client; an unmounted route must always dispose its channel. */
  dispose(): void;
  /**
   * Publishes the route's current `source: page` state. Returns false until the
   * runtime's `hello` confirms channelVersion 1.1.0 or later.
   */
  publishState(state: Record<string, unknown>): boolean;
}

interface ChannelEvent {
  readonly type: string;
  readonly channelVersion?: string;
  readonly requestId?: string;
  readonly capabilityId?: string;
  readonly actionId?: string;
  readonly input?: unknown;
  readonly reason?: string;
}

function delay(ms: number): Promise<void> {
  return new Promise((resolveDelay) => {
    setTimeout(resolveDelay, ms);
  });
}

function normalizeError(error: unknown): {
  code: string;
  category: string;
  message: string;
  retryable: boolean;
} {
  const message = error instanceof Error ? error.message : String(error);
  const code =
    error !== null && typeof error === "object" && typeof (error as { code?: unknown }).code === "string"
      ? (error as { code: string }).code
      : "web_action_failed";
  return { code, category: "capability", message, retryable: false };
}

async function postUplink(message: Record<string, unknown>): Promise<void> {
  try {
    await fetch("/_thefoolai/v1/web-channel/invoke", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(message),
    });
  } catch {
    // The stream is gone; the runtime already failed the invocation fail-closed.
  }
}

/**
 * Connects the standard Web Channel for one mounted route. Call this when the route installs its
 * agent bridge and `dispose()` on unmount — exactly one channel per page, latest page wins.
 */
export function connectWebChannel(
  surface: WebChannelActionSurface,
  options: WebChannelClientOptions = {},
): WebChannelClient {
  const maxReconnects = options.maxReconnects ?? 5;
  const controller = new AbortController();
  let disposed = false;
  let connected = false;
  let statePublishAllowed = false;
  let attempts = 0;

  const setConnected = (value: boolean) => {
    if (connected === value) return;
    connected = value;
    options.onStateChange?.(value);
  };

  async function handleEvent(event: ChannelEvent): Promise<"continue" | "stop"> {
    if (event.type === "superseded") return "stop";
    if (event.type === "hello") {
      statePublishAllowed = supportsStatePublish(event.channelVersion);
      if (statePublishAllowed) options.onChannelReady?.();
      return "continue";
    }
    if (event.type !== "invoke") return "continue";
    const requestId = typeof event.requestId === "string" ? event.requestId : "";
    if (requestId.length === 0) return "continue";
    const actionId = typeof event.actionId === "string" ? event.actionId : event.capabilityId;
    if (typeof actionId !== "string" || actionId.length === 0) {
      await postUplink({
        type: "error",
        requestId,
        error: {
          code: "invalid_web_channel_message",
          category: "protocol",
          message: "invoke message carried no actionId",
          retryable: false,
        },
      });
      return "continue";
    }
    try {
      const result = await surface.invoke(actionId, event.input ?? {});
      await postUplink({ type: "result", requestId, result });
    } catch (error) {
      await postUplink({ type: "error", requestId, error: normalizeError(error) });
    }
    return "continue";
  }

  void (async () => {
    while (!disposed) {
      try {
        const response = await fetch(
          `/_thefoolai/v1/web-channel?routeId=${encodeURIComponent(surface.routeId)}`,
          { headers: { accept: "text/event-stream" }, signal: controller.signal },
        );
        if (!response.ok || response.body === null) {
          throw new Error(`web channel connect failed: ${response.status}`);
        }
        setConnected(true);
        const reader = response.body.getReader();
        const decoder = new TextDecoder();
        let buffer = "";
        for (;;) {
          const { done, value } = await reader.read();
          if (done) break;
          // A successful response alone is not evidence that the channel is healthy: the runtime
          // sends `hello` immediately. Reset the bounded reconnect budget only after bytes arrive,
          // so an endpoint that repeatedly accepts and closes without a frame still converges.
          if (value.length > 0) attempts = 0;
          buffer += decoder.decode(value, { stream: true });
          let separator = buffer.indexOf("\n\n");
          while (separator !== -1) {
            const frame = buffer.slice(0, separator);
            buffer = buffer.slice(separator + 2);
            separator = buffer.indexOf("\n\n");
            for (const line of frame.split("\n")) {
              if (!line.startsWith("data: ")) continue;
              let event: ChannelEvent;
              try {
                event = JSON.parse(line.slice("data: ".length)) as ChannelEvent;
              } catch {
                continue;
              }
              if ((await handleEvent(event)) === "stop") {
                controller.abort();
                return;
              }
            }
          }
        }
      } catch {
        // Aborted, superseded or the runtime went away; fall through to the backoff policy.
      } finally {
        setConnected(false);
        statePublishAllowed = false;
      }
      if (disposed) return;
      attempts += 1;
      if (attempts > maxReconnects) return;
      await delay(Math.min(500 * 2 ** (attempts - 1), 8_000));
    }
  })();

  return {
    get connected() {
      return connected;
    },
    dispose() {
      disposed = true;
      controller.abort();
      setConnected(false);
      statePublishAllowed = false;
    },
    publishState(state) {
      if (!connected || !statePublishAllowed) return false;
      void postUplink({
        type: "statePublish",
        routeId: surface.routeId,
        state,
      });
      return true;
    },
  };
}
